package cn.mop.persistence;
import cn.mop.domain.*;
import cn.mop.domain.manualincident.*;
import cn.mop.domain.manualincident.ManualRecoveryRepository.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import com.zaxxer.hikari.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import java.sql.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Supplier;
import static org.junit.jupiter.api.Assertions.*;

/** Actual PG human evidence transactions over explicitly synthetic manual registrations. No monitored recovery or ticket transition. */
@EnabledIfEnvironmentVariable(named="MOP_RUN_REMOTE_TESTS",matches="true")
class PostgresManualRecoveryIntegrationTest {
    static final String TENANT="55000000-0000-4000-8000-000000000001",OTHER="55000000-0000-4000-8000-000000000002";
    static HikariDataSource pool;static ObjectMapper mapper;static PostgresPlatformRepository platform;static PostgresManualIncidentRepository incidents;static PostgresManualRecoveryRepository recoveries;static String engineer,admin,viewer,tadmin;
    @BeforeAll static void connect(){String url=System.getenv("SPRING_DATASOURCE_URL");assertNotNull(url);assertTrue(url.matches("jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/mop_test"));assertEquals("mop_test_runtime",System.getenv("SPRING_DATASOURCE_USERNAME"));var cfg=new HikariConfig();cfg.setJdbcUrl(url);cfg.setUsername(System.getenv("SPRING_DATASOURCE_USERNAME"));cfg.setPassword(System.getenv("SPRING_DATASOURCE_PASSWORD"));cfg.setMaximumPoolSize(6);cfg.setConnectionTimeout(5000);pool=new HikariDataSource(cfg);mapper=new ObjectMapper().registerModule(new JavaTimeModule()).setPropertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE).disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);platform=new PostgresPlatformRepository(pool,mapper);incidents=new PostgresManualIncidentRepository(pool,platform);recoveries=new PostgresManualRecoveryRepository(pool,platform);engineer=actor("msp",TENANT);admin=actor("padmin",TENANT);viewer=actor("viewer",TENANT);tadmin=actor("tadmin",TENANT);assertEquals(List.of(),recoveries.readinessProblems());}
    @AfterAll static void close(){if(pool!=null)pool.close();}
    static String actor(String role,String tenant){return platform.users().stream().filter(u->platform.membership(u.id(),tenant).filter(m->m.role().equals(role)).isPresent()).findFirst().orElseThrow().id();}
    static Access access(String actor){return new Access(actor,TENANT,platform.membership(actor,TENANT).orElseThrow().permissionVersion(),UUID.randomUUID().toString());}
    static ManualIncidentRepository.Entry parent(){return parent(TENANT,engineer);}
    static ManualIncidentRepository.Entry parent(String tenant,String actor){Asset asset=platform.list(tenant).get(0);var a=new ManualIncidentRepository.Access(actor,tenant,platform.membership(actor,tenant).orElseThrow().permissionVersion(),UUID.randomUUID().toString());return (ManualIncidentRepository.Entry)platform.idempotentAuthorized(actor,tenant,"POST /integration/recovery-parent",UUID.randomUUID().toString(),"a".repeat(64),a.permissionVersion(),()->incidents.authorizeCurrentAsset(a,asset.id()),()->incidents.create(a,new ManualIncident("RECOVERY-TEST-"+UUID.randomUUID(),ManualIncident.Severity.INFO,asset.id(),asset.version())));}
    static Object command(PostgresPlatformRepository p,PostgresManualRecoveryRepository repo,Access a,String parent,String route,String key,String hash,Supplier<Object> action){return p.idempotentAuthorized(a.actorId(),a.tenantId(),route,key,hash,a.permissionVersion(),()->repo.authorizeCurrentIncident(a,parent),action);}
    static Confirmation confirm(String parent,String actor,ManualRecoveryConfirmation value){Access a=access(actor);return (Confirmation)command(platform,recoveries,a,parent,"POST /integration/manual-recovery",UUID.randomUUID().toString(),"a".repeat(64),()->recoveries.confirm(a,parent,0,value));}
    static long count(String parent)throws SQLException{try(var c=pool.getConnection();var s=c.prepareStatement("SELECT count(*) FROM public.mop_manual_recovery_confirmation WHERE tenant_id=?::uuid AND incident_id=?::uuid")){s.setString(1,TENANT);s.setString(2,parent);try(var r=s.executeQuery()){r.next();return r.getLong(1);}}}
    static long audits(String id)throws SQLException{try(var c=pool.getConnection();var s=c.prepareStatement("SELECT count(*) FROM public.mop_audit WHERE tenant_id=?::uuid AND payload->>'action'='manual_incident.recovery.confirm' AND payload->>'resource_id'=?")){s.setString(1,TENANT);s.setString(2,id);try(var r=s.executeQuery()){r.next();return r.getLong(1);}}}
    static JsonNode json(Object value)throws Exception{return mapper.readTree(mapper.writeValueAsBytes(value));}
    @Test void initialAbsenceIsExplicitVersionZeroNotAnInventedRecovery(){var parent=parent();Current current=recoveries.get(access(engineer),parent.id());assertEquals(0,current.version());assertEquals("NOT_CONFIRMED",current.manualRecoveryStatus());assertNull(current.confirmation());}
    @Test void rawHumanEvidenceRoundTripsThroughIndependentRepository()throws Exception{var parent=parent();var value=new ManualRecoveryConfirmation("  人工核验😀\r\n原始说明\t ",null);Confirmation saved=confirm(parent.id(),engineer,value);assertEquals(value,saved.value());assertEquals(engineer,saved.actorId());assertEquals(TENANT,saved.tenantId());assertEquals(parent.id(),saved.incidentId());assertNotNull(saved.recordedAt());var current=new PostgresManualRecoveryRepository(pool,new PostgresPlatformRepository(pool,mapper)).get(access(admin),parent.id());assertEquals(1,current.version());assertEquals("HUMAN_CONFIRMED",current.manualRecoveryStatus());assertEquals(saved,current.confirmation());assertNull(saved.value().reportedRecoveredAt());assertEquals(1,audits(saved.id()));}
    @Test void confirmationDoesNotRewriteOriginalRegistrationOrCreateATicket()throws SQLException{var parent=parent();long tickets;try(var c=pool.getConnection();var s=c.createStatement();var r=s.executeQuery("SELECT count(*) FROM public.mop_ticket")){r.next();tickets=r.getLong(1);}var saved=confirm(parent.id(),admin,new ManualRecoveryConfirmation("合成人工确认",null));var a=new ManualIncidentRepository.Access(engineer,TENANT,access(engineer).permissionVersion(),"synthetic");assertEquals(parent,incidents.get(a,parent.id()));assertEquals("NOT_CONFIRMED",incidents.get(a,parent.id()).incident().manualRecoveryStatus());assertNull(saved.value().monitorState());assertNull(saved.value().dispositionState());assertFalse(saved.value().ticketStateChanged());assertFalse(saved.value().slaChanged());try(var c=pool.getConnection();var s=c.createStatement();var r=s.executeQuery("SELECT count(*) FROM public.mop_ticket")){r.next();assertEquals(tickets,r.getLong(1));}}
    @Test void bothCurrentInternalRolesCanConfirmButCustomerRolesCannotReadOrConfirm()throws SQLException{for(String role:List.of(engineer,admin)){var parent=parent();Confirmation saved=confirm(parent.id(),role,new ManualRecoveryConfirmation("human",null));assertEquals(saved,recoveries.get(access(engineer),parent.id()).confirmation());}var parent=parent();for(String user:List.of(viewer,tadmin)){assertEquals(403,assertThrows(DomainException.class,()->recoveries.get(access(user),parent.id())).status);assertEquals(403,assertThrows(DomainException.class,()->confirm(parent.id(),user,new ManualRecoveryConfirmation("forbidden",null))).status);}assertEquals(0,count(parent.id()));}
    @Test void foreignOrMissingManualParentIsHiddenBeforeConfirmationCas(){var foreign=parent(OTHER,actor("padmin",OTHER));Access a=access(engineer);assertEquals(404,assertThrows(DomainException.class,()->recoveries.get(a,foreign.id())).status);assertEquals(404,assertThrows(DomainException.class,()->command(platform,recoveries,a,foreign.id(),"POST /integration/foreign-recovery",UUID.randomUUID().toString(),"a".repeat(64),()->recoveries.confirm(a,foreign.id(),1,new ManualRecoveryConfirmation("foreign",null)))).status);assertEquals(404,assertThrows(DomainException.class,()->recoveries.get(a,UUID.randomUUID().toString())).status);}
    @Test void staleMissingAndMalformedMembershipFailsClosed(){var parent=parent();Access a=access(engineer);for(Access wrong:List.of(new Access(a.actorId(),TENANT,a.permissionVersion()+1,"synthetic"),new Access(UUID.randomUUID().toString(),TENANT,1,"synthetic"),new Access("bad",TENANT,1,"synthetic"))){assertEquals(401,assertThrows(DomainException.class,()->recoveries.get(wrong,parent.id())).status);}assertEquals(401,assertThrows(DomainException.class,()->recoveries.get(null,parent.id())).status);}
    @Test void unprotectedWritesAndReplayGuardsCannotBorrowAnUnrelatedConnection(){var parent=parent();Access a=access(engineer);assertThrows(IllegalStateException.class,()->recoveries.confirm(a,parent.id(),0,new ManualRecoveryConfirmation("unguarded",null)));assertThrows(IllegalStateException.class,()->recoveries.authorizeCurrentIncident(a,parent.id()));}
    @Test void originalKeyReturnsOriginalEvidenceWithoutDuplicateAudit()throws Exception{var parent=parent();Access a=access(engineer);String key=UUID.randomUUID().toString(),route="POST /integration/recovery-replay";Object first=command(platform,recoveries,a,parent.id(),route,key,"a".repeat(64),()->recoveries.confirm(a,parent.id(),0,new ManualRecoveryConfirmation("original",null)));Object replay=command(platform,recoveries,a,parent.id(),route,key,"a".repeat(64),()->{throw new AssertionError("Replay cannot execute");});assertEquals(json(first),json(replay));assertEquals(1,count(parent.id()));assertEquals(1,audits(((Confirmation)first).id()));assertEquals(409,assertThrows(DomainException.class,()->command(platform,recoveries,a,parent.id(),route,key,"b".repeat(64),()->null)).status);}
    @Test void replayReauthorizesParentAndPermissionBeforeCachedReceipt()throws Exception{var parent=parent();Access a=access(engineer);String key=UUID.randomUUID().toString(),route="POST /integration/recovery-fresh-guard";var saved=(Confirmation)command(platform,recoveries,a,parent.id(),route,key,"a".repeat(64),()->recoveries.confirm(a,parent.id(),0,new ManualRecoveryConfirmation("original",null)));var foreign=parent(OTHER,actor("padmin",OTHER));assertEquals(404,assertThrows(DomainException.class,()->command(platform,recoveries,a,foreign.id(),route,key,"a".repeat(64),()->null)).status);Access stale=new Access(a.actorId(),a.tenantId(),a.permissionVersion()+1,a.traceId());assertEquals(401,assertThrows(DomainException.class,()->command(platform,recoveries,stale,parent.id(),route,key,"a".repeat(64),()->null)).status);assertEquals(1,audits(saved.id()));}
    @Test void separateNewRequestsCannotOverwriteAnExistingConfirmation()throws SQLException{var parent=parent();var value=new ManualRecoveryConfirmation("first",null);var saved=confirm(parent.id(),engineer,value);assertEquals(409,assertThrows(DomainException.class,()->confirm(parent.id(),admin,new ManualRecoveryConfirmation("second",null))).status);Access a=access(admin);assertEquals(422,assertThrows(DomainException.class,()->command(platform,recoveries,a,parent.id(),"POST /integration/recovery-already-confirmed",UUID.randomUUID().toString(),"a".repeat(64),()->recoveries.confirm(a,parent.id(),1,value))).status);assertEquals(saved,recoveries.get(a,parent.id()).confirmation());assertEquals(1,count(parent.id()));}
    @Test void downstreamFailureRollsBackEvidenceAuditAndReceiptBeforeSameKeyRetry()throws Exception{var parent=parent();Access a=access(engineer);String key=UUID.randomUUID().toString(),route="POST /integration/recovery-rollback";Confirmation[] attempted=new Confirmation[1];assertThrows(IllegalStateException.class,()->command(platform,recoveries,a,parent.id(),route,key,"a".repeat(64),()->{attempted[0]=recoveries.confirm(a,parent.id(),0,new ManualRecoveryConfirmation("rollback",null));throw new IllegalStateException("Synthetic downstream failure");}));assertEquals(0,count(parent.id()));assertEquals(0,audits(attempted[0].id()));assertEquals(0,recoveries.get(a,parent.id()).version());var saved=(Confirmation)command(platform,recoveries,a,parent.id(),route,key,"a".repeat(64),()->recoveries.confirm(a,parent.id(),0,new ManualRecoveryConfirmation("rollback",null)));assertEquals(1,audits(saved.id()));}
    @Test void sameKeyConcurrentIndependentConnectionsCommitExactlyOneEvidence()throws Exception{var parent=parent();Access a=access(engineer);String key=UUID.randomUUID().toString(),route="POST /integration/recovery-concurrent-key";var executor=Executors.newFixedThreadPool(2);var ready=new CountDownLatch(2);var start=new CountDownLatch(1);try{List<Future<Object>> futures=new ArrayList<>();for(int i=0;i<2;i++)futures.add(executor.submit(()->{var p=new PostgresPlatformRepository(pool,mapper);var repo=new PostgresManualRecoveryRepository(pool,p);ready.countDown();assertTrue(start.await(10,TimeUnit.SECONDS));return command(p,repo,a,parent.id(),route,key,"a".repeat(64),()->repo.confirm(a,parent.id(),0,new ManualRecoveryConfirmation("same original",null)));}));assertTrue(ready.await(10,TimeUnit.SECONDS));start.countDown();Object first=futures.get(0).get(15,TimeUnit.SECONDS);assertEquals(json(first),json(futures.get(1).get(15,TimeUnit.SECONDS)));assertEquals(1,count(parent.id()));assertEquals(1,audits(json(first).get("id").asText()));}finally{executor.shutdownNow();}}
    @Test void differentKeyConcurrentHumansHaveOneWinnerAndOneVersionConflict()throws Exception{var parent=parent();var executor=Executors.newFixedThreadPool(2);var start=new CountDownLatch(1);var ready=new CountDownLatch(2);try{List<Future<Object>> futures=new ArrayList<>();for(String actor:List.of(engineer,admin))futures.add(executor.submit(()->{Access a=access(actor);var p=new PostgresPlatformRepository(pool,mapper);var repo=new PostgresManualRecoveryRepository(pool,p);ready.countDown();assertTrue(start.await(10,TimeUnit.SECONDS));try{return command(p,repo,a,parent.id(),"POST /integration/recovery-race",UUID.randomUUID().toString(),"a".repeat(64),()->repo.confirm(a,parent.id(),0,new ManualRecoveryConfirmation("separate human",null)));}catch(DomainException e){return e;}}));assertTrue(ready.await(10,TimeUnit.SECONDS));start.countDown();List<Object> results=new ArrayList<>();for(var f:futures)results.add(f.get(15,TimeUnit.SECONDS));assertEquals(1,results.stream().filter(Confirmation.class::isInstance).count());assertEquals(1,results.stream().filter(v->v instanceof DomainException e&&e.status==409).count());assertEquals(1,count(parent.id()));assertEquals(1,audits(recoveries.get(access(engineer),parent.id()).confirmation().id()));}finally{executor.shutdownNow();}}
    @Test void explicitHistoricalTimeAndMaximumUnicodePersistWhileFutureAssertionIsRejected()throws SQLException{var parent=parent();assertEquals(400,assertThrows(DomainException.class,()->confirm(parent.id(),engineer,new ManualRecoveryConfirmation("future",Instant.parse("9999-12-31T23:59:59.999Z")))).status);assertEquals(0,count(parent.id()));Instant historical=Instant.parse("2020-02-29T00:00:00.123Z");var value=new ManualRecoveryConfirmation("😀".repeat(2000),historical);var saved=confirm(parent.id(),engineer,value);assertEquals(value,recoveries.get(access(admin),parent.id()).confirmation().value());assertTrue(saved.recordedAt().isAfter(historical));try(var c=pool.getConnection();var s=c.createStatement();var r=s.executeQuery("SELECT has_any_column_privilege(current_user,'public.mop_manual_incident_registration','UPDATE')")){r.next();assertFalse(r.getBoolean(1));}}
}
